        add("parameter.noneRequired", "No user parameters are required.", "User parameters आवश्यक नाहीत.", "कोई user parameter आवश्यक नहीं है।", "কোনো user parameter দরকার নেই।", "User parameters જરૂરી નથી.", "User parameters தேவையில்லை.", "User parameters అవసరం లేదు.", "User parameters ಅಗತ್ಯವಿಲ್ಲ.", "User parameters ആവശ്യമില്ല.", "No se requieren parámetros de usuario.");
        add("parameter.formatsMatch", "Count and supported primitive formats match.", "संख्या आणि समर्थित primitive formats जुळतात.", "संख्या और समर्थित primitive formats मेल खाते हैं।", "সংখ্যা ও সমর্থিত primitive formats মেলে।", "સંખ્યા અને સમર્થિત primitive formats મેળ ખાય છે.", "எண்ணிக்கையும் ஆதரிக்கப்படும் primitive formats-மும் பொருந்துகின்றன.", "సంఖ్య మరియు మద్దతున్న primitive formats సరిపోతున్నాయి.", "ಎಣಿಕೆ ಮತ್ತು ಬೆಂಬಲಿತ primitive formats ಹೊಂದಿಕೆಯಾಗುತ್ತವೆ.", "എണ്ണവും പിന്തുണയ്ക്കുന്ന primitive formats-ഉം പൊരുത്തപ്പെടുന്നു.", "La cantidad y los formatos primitivos compatibles coinciden.");
        add("parameter.booleanInvalid", "Boolean parameter {0} must be true or false.", "Boolean parameter {0} true किंवा false असणे आवश्यक.", "Boolean parameter {0} true या false होना चाहिए।", "Boolean parameter {0} true বা false হতে হবে।", "Boolean parameter {0} true અથવા false હોવું જોઈએ.", "Boolean parameter {0} true அல்லது false ஆக இருக்க வேண்டும்.", "Boolean parameter {0} true లేదా false కావాలి.", "Boolean parameter {0} true ಅಥವಾ false ಆಗಿರಬೇಕು.", "Boolean parameter {0} true അല്ലെങ്കിൽ false ആയിരിക്കണം.", "El parámetro booleano {0} debe ser true o false.");
        add("parameter.invalidType", "Parameter {0} is not valid for {1}.", "Parameter {0}, {1} साठी वैध नाही.", "Parameter {0}, {1} के लिए मान्य नहीं है।", "Parameter {0}, {1}-এর জন্য বৈধ নয়।", "Parameter {0}, {1} માટે માન્ય નથી.", "Parameter {0}, {1}-க்கு செல்லாது.", "Parameter {0}, {1}కు చెల్లదు.", "Parameter {0}, {1}ಗೆ ಮಾನ್ಯವಲ್ಲ.", "Parameter {0}, {1}-ന് സാധുവല്ല.", "El parámetro {0} no es válido para {1}.");
        add("parameter.typeUnknown", "Parameter {0} uses a type the guide cannot validate.", "Parameter {0} चा type Guide तपासू शकत नाही.", "Parameter {0} का type Guide सत्यापित नहीं कर सकता।", "Parameter {0}-এর type Guide যাচাই করতে পারে না।", "Parameter {0} નો type Guide ચકાસી શકતું નથી.", "Parameter {0}-ன் type-ஐ Guide சரிபார்க்க முடியாது.", "Parameter {0} type‌ను Guide ధృవీకరించలేడు.", "Parameter {0} type ಅನ್ನು Guide ಪರಿಶೀಲಿಸಲಾಗುವುದಿಲ್ಲ.", "Parameter {0}-ന്റെ type Guide-ന് പരിശോധിക്കാനാവില്ല.", "Guide no puede validar el tipo del parámetro {0}.");
        add("parameter.complexUnknown", "Argument count matches; complex values are not fully validated.", "Argument संख्या जुळते; complex values पूर्ण तपासलेले नाहीत.", "Argument संख्या मेल खाती है; complex values पूरी तरह सत्यापित नहीं हैं।", "Argument সংখ্যা মেলে; complex values পুরোপুরি যাচাই হয়নি।", "Argument સંખ્યા મેળ ખાય છે; complex values સંપૂર્ણ ચકાસ્યા નથી.", "Argument எண்ணிக்கை பொருந்துகிறது; complex values முழுமையாக சரிபார்க்கப்படவில்லை.", "Argument సంఖ్య సరిపోతుంది; complex values పూర్తిగా ధృవీకరించలేదు.", "Argument ಎಣಿಕೆ ಹೊಂದಿದೆ; complex values ಸಂಪೂರ್ಣವಾಗಿ ಪರಿಶೀಲಿಸಿಲ್ಲ.", "Argument എണ്ണം പൊരുത്തപ്പെടുന്നു; complex values പൂർണ്ണമായി പരിശോധിച്ചിട്ടില്ല.", "La cantidad coincide; los valores complejos no se validaron por completo.");
        add("execution.lastFailed", "The last method execution failed.", "शेवटची method अंमलबजावणी अयशस्वी झाली.", "अंतिम method निष्पादन विफल हुआ।", "শেষ method কার্যসম্পাদন ব্যর্থ হয়েছে।", "છેલ્લી method અમલ નિષ્ફળ ગઈ.", "கடைசி method செயல்பாடு தோல்வியடைந்தது.", "చివరి method అమలు విఫలమైంది.", "ಕೊನೆಯ method ಕಾರ್ಯಗತಗೊಳಿಸುವಿಕೆ ವಿಫಲವಾಗಿದೆ.", "അവസാന method നിർവഹണം പരാജയപ്പെട്ടു.", "Falló la última ejecución del método.");
        add("execution.failedSolution", "Check target compatibility, parameter values, and the method signature.", "Target compatibility, parameter values आणि method signature तपासा.", "Target compatibility, parameter values और method signature जाँचें।", "Target compatibility, parameter values ও method signature পরীক্ষা করুন।", "Target compatibility, parameter values અને method signature તપાસો.", "Target compatibility, parameter values மற்றும் method signature-ஐச் சரிபார்க்கவும்.", "Target compatibility, parameter values మరియు method signature తనిఖీ చేయండి.", "Target compatibility, parameter values ಮತ್ತು method signature ಪರಿಶೀಲಿಸಿ.", "Target compatibility, parameter values, method signature എന്നിവ പരിശോധിക്കുക.", "Compruebe la compatibilidad del objetivo, los parámetros y la firma del método.");
        add("problem.dex", "DEX verification failed.", "DEX पडताळणी अयशस्वी.", "DEX सत्यापन विफल हुआ।", "DEX যাচাই ব্যর্থ হয়েছে।", "DEX ચકાસણી નિષ્ફળ ગઈ.", "DEX சரிபார்ப்பு தோல்வியடைந்தது.", "DEX ధృవీకరణ విఫలమైంది.", "DEX ಪರಿಶೀಲನೆ ವಿಫಲವಾಗಿದೆ.", "DEX പരിശോധന പരാജയപ്പെട്ടു.", "Falló la verificación de DEX.");
