        add("guide.dynamic.goal.parameters", "Explain this Method's Parameters", "या Method चे Parameters समजावून सांगा", "इस Method के Parameters समझाएँ", "এই Method-এর Parameters বুঝিয়ে দিন", "આ Method ના Parameters સમજાવો", "இந்த Method-ன் Parameters விளக்கவும்", "ఈ Method Parameters వివరించండి", "ಈ Method‌ನ Parameters ವಿವರಿಸಿ", "ഈ Method-ന്റെ Parameters വിശദീകരിക്കുക", "Explica los parámetros de este método");
        add("guide.dynamic.goal.values", "Help me configure input Values", "Input Values सेट करण्यात मदत करा", "Input Values सेट करने में मदद करें", "Input Values সেট করতে সাহায্য করুন", "Input Values સેટ કરવામાં મદદ કરો", "Input Values அமைக்க உதவுங்கள்", "Input Values అమర్చడంలో సహాయం చేయండి", "Input Values ಹೊಂದಿಸಲು ಸಹಾಯ ಮಾಡಿ", "Input Values ക്രമീകരിക്കാൻ സഹായിക്കുക", "Ayúdame a configurar los valores");
        add("guide.dynamic.goal.providers", "Help me connect a Provider", "Provider जोडण्यात मदत करा", "Provider जोड़ने में मदद करें", "Provider সংযোগে সাহায্য করুন", "Provider જોડવામાં મદદ કરો", "Provider இணைக்க உதவுங்கள்", "Provider అనుసంధానించడంలో సహాయం చేయండి", "Provider ಸಂಪರ್ಕಿಸಲು ಸಹಾಯ ಮಾಡಿ", "Provider ബന്ധിപ്പിക്കാൻ സഹായിക്കുക", "Ayúdame a conectar un Provider");
        add("guide.dynamic.goal.getters", "Help me understand Getter usage", "Getter चा वापर समजावून सांगा", "Getter का उपयोग समझाएँ", "Getter-এর ব্যবহার বুঝিয়ে দিন", "Getter નો ઉપયોગ સમજાવો", "Getter பயன்பாட்டை விளக்கவும்", "Getter వినియోగాన్ని వివరించండి", "Getter ಬಳಕೆಯನ್ನು ವಿವರಿಸಿ", "Getter ഉപയോഗം വിശദീകരിക്കുക", "Ayúdame a entender el uso de Getter");
        add("guide.dynamic.goal.order", "Help me understand execution order", "Execution क्रम समजावून सांगा", "Execution क्रम समझाएँ", "Execution-এর ক্রম বুঝিয়ে দিন", "Execution ક્રમ સમજાવો", "Execution வரிசையை விளக்கவும்", "Execution క్రమాన్ని వివరించండి", "Execution ಕ್ರಮವನ್ನು ವಿವರಿಸಿ", "Execution ക്രമം വിശദീകരിക്കുക", "Ayúdame a entender el orden de ejecución");
        add("guide.dynamic.goal.diagnose", "Help me diagnose an error", "Error शोधण्यात मदत करा", "Error का निदान करने में मदद करें", "Error নির্ণয়ে সাহায্য করুন", "Error શોધવામાં મદદ કરો", "Error கண்டறிய உதவுங்கள்", "Error గుర్తించడంలో సహాయం చేయండి", "Error ಪತ್ತೆಹಚ್ಚಲು ಸಹಾಯ ಮಾಡಿ", "Error കണ്ടെത്താൻ സഹായിക്കുക", "Ayúdame a diagnosticar un error");
        add("guide.dynamic.explanation", "The project data below is based on the currently loaded DEX and verified metadata.", "खालील Project माहिती सध्याच्या DEX आणि पडताळलेल्या metadata वर आधारित आहे.", "नीचे दी गई Project जानकारी वर्तमान DEX और सत्यापित metadata पर आधारित है।", "", "", "", "", "", "", "");
        add("guide.dynamic.purposeUnknown", "The project purpose is not established by the available description. Method names and signatures alone do not prove functionality.", "उपलब्ध description मधून Project चा हेतू निश्चित होत नाही. Method नावे आणि signatures एवढ्याने कार्य सिद्ध होत नाही.", "उपलब्ध description से Project का उद्देश्य तय नहीं होता। केवल Method नाम और signatures से कार्य सिद्ध नहीं होता।", "", "", "", "", "", "", "");
        add("guide.dynamic.noMethods", "No callable Methods were discovered from the loaded DEX. Check the extension load status and DEX.", "लोड केलेल्या DEX मधून callable Methods सापडले नाहीत. Extension load स्थिती आणि DEX तपासा.", "लोड किए गए DEX में callable Methods नहीं मिले। Extension load स्थिति और DEX जाँचें।", "", "", "", "", "", "", "");
        add("guide.dynamic.methodMissing", "Select a Method in this Guide to inspect its signature and available information.", "Signature आणि उपलब्ध माहिती पाहण्यासाठी Guide मधून Method निवडा.", "Signature और उपलब्ध जानकारी देखने के लिए Guide में Method चुनें।", "", "", "", "", "", "", "");
        add("guide.dynamic.noParameters", "This Method has no user-supplied Parameters.", "या Method ला वापरकर्त्याने द्यायचे Parameters नाहीत.", "इस Method में उपयोगकर्ता द्वारा दिए जाने वाले Parameters नहीं हैं।", "", "", "", "", "", "", "");
        add("guide.dynamic.incompleteParameter", "Parameter information is incomplete.", "Parameter ची माहिती अपूर्ण आहे.", "Parameter की जानकारी अधूरी है।", "", "", "", "", "", "", "");
        add("guide.dynamic.listFormatUnknown", "The list element type or format cannot be determined from the available metadata.", "उपलब्ध metadata मधून List element चा type किंवा format ठरवता येत नाही.", "उपलब्ध metadata से List element का type या format तय नहीं किया जा सकता।", "", "", "", "", "", "", "");
        add("guide.dynamic.requiredUnknown", "Required or optional status is not specified in the available metadata.", "उपलब्ध metadata मध्ये required किंवा optional स्थिती नमूद नाही.", "उपलब्ध metadata में required या optional स्थिति नहीं बताई गई है।", "", "", "", "", "", "", "");
        add("guide.dynamic.defaultInvalid", "A metadata default exists but could not be validated for the Java type.", "Metadata default आहे, पण तो Java type साठी validate झाला नाही.", "Metadata default मौजूद है, लेकिन Java type के लिए validate नहीं हुआ।", "", "", "", "", "", "", "");
        add("guide.dynamic.noDefault", "No verified default is available.", "पडताळलेली default value उपलब्ध नाही.", "कोई सत्यापित default उपलब्ध नहीं है।", "", "", "", "", "", "", "");
        add("guide.dynamic.providerTypeOnly", "Type compatibility does not prove semantic suitability. Choose a Provider explicitly; this Guide does not change the connection.", "Type compatibility म्हणजे योग्य अर्थाचा पुरावा नाही. Provider स्वतः निवडा; Guide connection बदलत नाही.", "Type compatibility से अर्थ की उपयुक्तता सिद्ध नहीं होती। Provider स्वयं चुनें; Guide connection नहीं बदलेगा।", "", "", "", "", "", "", "");
        add("guide.dynamic.goalNoMatch", "No clear text match was found. Choose a Method from the list; the Guide will not guess its purpose.", "स्पष्ट मजकूर जुळणी सापडली नाही. यादीतून Method निवडा; Guide हेतूचा अंदाज लावणार नाही.", "स्पष्ट text match नहीं मिला। सूची से Method चुनें; Guide उद्देश्य का अनुमान नहीं लगाएगा।", "", "", "", "", "", "", "");
        add("guide.dynamic.candidateHeader", "Text matches only; semantic suitability is not guaranteed.", "हे फक्त मजकूर जुळणारे पर्याय आहेत; अर्थपूर्ण योग्यतेची खात्री नाही.", "ये केवल text matches हैं; अर्थ की उपयुक्तता की गारंटी नहीं है।", "", "", "", "", "", "", "");
        add("guide.dynamic.selectCandidate", "Review a candidate and select it explicitly. The Guide never auto-selects a Method.", "पर्याय तपासून स्पष्टपणे निवडा. Guide Method आपोआप निवडत नाही.", "उम्मीदवार जाँचकर स्पष्ट रूप से चुनें। Guide Method को अपने आप नहीं चुनता।", "", "", "", "", "", "", "");
        add("guide.dynamic.goalLabel", "Goal", "ध्येय", "लक्ष्य", "", "", "", "", "", "", "");
        add("guide.dynamic.extensionDescription", "Extension description (annotation)", "Extension description (annotation)", "Extension description (annotation)", "", "", "", "", "", "", "");
        add("guide.dynamic.methodDescriptionMissing", "No verified Method description is available; its purpose is not inferred.", "पडताळलेले Method description उपलब्ध नाही; हेतूचा अंदाज लावलेला नाही.", "सत्यापित Method description उपलब्ध नहीं है; उद्देश्य का अनुमान नहीं लगाया गया।", "", "", "", "", "", "", "");
        add("guide.dynamic.signatureBasis", "Parameters are read from the reflected Java signature. Defaults are shown only when metadata values validate; absent range, format, or required status is reported as unknown.", "Parameters Reflection मधील Java signature वरून घेतले आहेत. Metadata value validate झाल्यासच default दाखवतो; range, format किंवा required स्थिती नसल्यास ती अज्ञात दाखवतो.", "Parameters reflected Java signature से लिए गए हैं। Metadata value validate होने पर ही default दिखता है; range, format या required स्थिति न हो तो अज्ञात बताई जाती है।", "", "", "", "", "", "", "");
        add("guide.dynamic.editValues", "Edit values in the main Parameters row or Tune dialog. The Guide does not change inputs.", "Values मुख्य Parameters row किंवा Tune dialog मध्ये बदला. Guide inputs बदलत नाही.", "Values मुख्य Parameters row या Tune dialog में बदलें। Guide inputs नहीं बदलता।", "", "", "", "", "", "", "");
        add("guide.dynamic.noProvider", "No type-compatible verified Provider candidate was found for this Parameter.", "या Parameter साठी type-compatible पडताळलेला Provider सापडला नाही.", "इस Parameter के लिए type-compatible सत्यापित Provider नहीं मिला।", "", "", "", "", "", "", "");
        add("guide.dynamic.noGetter", "No compatible verified readable property is available for this Parameter.", "या Parameter साठी compatible पडताळलेली readable property उपलब्ध नाही.", "इस Parameter के लिए compatible सत्यापित readable property उपलब्ध नहीं है।", "", "", "", "", "", "", "");
        add("guide.dynamic.getterExisting", "Use the existing Getter control. This Guide does not resolve or execute Getter values.", "विद्यमान Getter control वापरा. Guide Getter value resolve किंवा execute करत नाही.", "मौजूदा Getter control का उपयोग करें। Guide Getter value resolve या execute नहीं करता।", "", "", "", "", "", "", "");
        add("guide.dynamic.executionOrder", "Existing execution order: selected Providers run by input index; each return value is converted to the target type and added to the override map; then the main Method runs.", "विद्यमान क्रम: निवडलेले Providers input index नुसार चालतात; प्रत्येक return value target type मध्ये convert होऊन override map मध्ये जाते; मग मुख्य Method चालतो.", "मौजूदा क्रम: चुने गए Providers input index के क्रम में चलते हैं; हर return value target type में convert होकर override map में जाती है; फिर मुख्य Method चलता है।", "", "", "", "", "", "", "");
        add("guide.dynamic.directExecution", "No Provider mapping is selected. The existing direct path runs the selected main Method:", "Provider mapping निवडलेले नाही. विद्यमान direct path निवडलेला मुख्य Method चालवतो:", "Provider mapping नहीं चुनी गई। मौजूदा direct path चुना हुआ मुख्य Method चलाता है:", "", "", "", "", "", "", "");
        add("guide.dynamic.guideNoExecute", "This Guide does not execute Methods or change configured values.", "हा Guide Methods चालवत नाही किंवा configured values बदलत नाही.", "यह Guide Methods execute नहीं करता और configured values नहीं बदलता।", "", "", "", "", "", "", "");
        add("guide.dynamic.chooseMethodFirst", "Choose a Method using the selector above to see this guidance.", "हे मार्गदर्शन पाहण्यासाठी वरील selector मधून Method निवडा.", "यह मार्गदर्शन देखने के लिए ऊपर के selector से Method चुनें।", "", "", "", "", "", "", "");
        add("guide.dynamic.errorChecksum", "Execution error records do not store a DEX checksum, so association with the current Project cannot be verified.", "Execution error record मध्ये DEX checksum नसतो; त्यामुळे तो सध्याच्या Project शी संबंधित आहे हे पडताळता येत नाही.", "Execution error record में DEX checksum नहीं होता; इसलिए उसे वर्तमान Project से जोड़ना verify नहीं किया जा सकता।", "", "", "", "", "", "", "");
        add("guide.dynamic.errorCaution", "The error was compared with available signatures and metadata. A cause is not stated as certain unless evidence supports it.", "Error ची उपलब्ध signatures आणि metadata शी तुलना केली आहे. पुरावा नसेल तर कारण निश्चित असल्याचे सांगितलेले नाही.", "Error की उपलब्ध signatures और metadata से तुलना की गई है। प्रमाण न हो तो कारण को निश्चित नहीं बताया गया है।", "", "", "", "", "", "", "");
        add("guide.dynamic.unknownGoalHint", "Describe what you want to accomplish. If descriptions do not clarify it, browse the Method list; purpose will not be inferred from a signature alone.", "तुम्हाला काय साध्य करायचे आहे ते लिहा. Description स्पष्ट नसेल तर Method यादी पाहा; फक्त signature वरून हेतू ठरवला जाणार नाही.", "आप क्या करना चाहते हैं लिखें। Description स्पष्ट न हो तो Method सूची देखें; केवल signature से उद्देश्य नहीं निकाला जाएगा।", "", "", "", "", "", "", "");
